create table public.meta_template_versions (
 name text not null,version integer not null,language text not null,definition jsonb not null,
 approval text not null default 'PREPARED' check(approval in ('PREPARED','SUBMITTED','PENDING','APPROVED','REJECTED','BLOCKED')),
 provider_id text,checked_at timestamptz,primary key(name,version,language)
);
alter table public.meta_template_versions enable row level security;
revoke all on public.meta_template_versions from public,anon,authenticated,service_role;
grant select on public.meta_template_versions to authenticated;
create policy templates_global_read on public.meta_template_versions for select to authenticated using(public.is_global_administrator());
create function public.bind_notification_template(p_id uuid,p_worker uuid,p_name text,p_version integer,p_language text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare t public.meta_template_versions;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_id,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into t from public.meta_template_versions where name=p_name and version=p_version and language=p_language;
 if not found then return null;end if;
 if t.approval='APPROVED' then update public.requisition_notifications set template_name=t.name,template_version=t.version,template_snapshot=t.definition where id=p_id;end if;
 return t.definition||jsonb_build_object('name',t.name,'version',t.version,'language',t.language,'approval',t.approval);
end;$$;
grant execute on function public.bind_notification_template(uuid,uuid,text,integer,text) to service_role;
create or replace function public.notification_document_payload(p_id uuid,p_worker_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare n public.requisition_notifications;d public.operational_documents;e public.document_events;begin
 if not public.validate_notification_job(p_id,p_worker_id) then raise exception 'invalid notification job' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_id;
 select * into d from public.operational_documents where id=coalesce(n.document_id,n.requisition_id);
 if not found then return null;end if;
 if n.document_event_id is not null then select * into e from public.document_events where id=n.document_event_id;
 else select * into e from public.document_events where document_id=d.id order by version limit 1;end if;
 return jsonb_build_object('documentId',d.id,'patientId',d.care_recipient_id,'code',d.code,'type',d.type,'protocol',d.protocol,'version',e.version,'snapshot',e.body,'hash',e.content_hash,
 'eventKey',coalesce(n.event_key,e.action),'recipientName',n.recipient_label,'isDesignatedRecipient',n.recipient_user_id=d.recipient_id,'includePdf',n.include_pdf,
 'shortPatientName',coalesce((select nullif(settings->>'patientShortName','') from public.patient_settings where care_recipient_id=d.care_recipient_id),e.body->'actors'->'patient'->>'name'));
end;$$;

-- Only verified external entry points can install a transaction-scoped actor.
-- It does not create an Auth session and cannot be selected by a browser.
create function private.has_patient_authority(p_patient uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from private.authority_sessions where session_id=private.auth_session() and user_id=auth.uid() and mode='patient' and care_recipient_id=p_patient)
 or exists(select 1 from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current() and user_id=auth.uid() and care_recipient_id=p_patient);
$$;
create or replace function public.recipient_role(p_recipient_id uuid) returns public.profile_role language sql stable security definer set search_path='' as $$
 select m.role from public.care_recipient_memberships m join public.profiles p on p.id=m.user_id
 where m.user_id=auth.uid() and m.care_recipient_id=p_recipient_id and m.status='active' and p.status='active' and private.has_patient_authority(p_recipient_id);
$$;
revoke all on function private.has_patient_authority(uuid) from public,anon,authenticated,service_role;

create or replace function public.accept_whatsapp_receipt(p_provider_id text,p_phone text,p_hash text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c public.whatsapp_challenges;d public.operational_documents;result jsonb;previous text:=current_setting('hca.verified_whatsapp_provider',true);begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'signed webhook worker required' using errcode='42501';end if;
 select * into c from public.whatsapp_challenges where token_hash=p_hash;
 if not found then return jsonb_build_object('accepted',false);end if;
 select * into strict d from public.operational_documents where id=c.document_id;
 insert into private.worker_authority values(pg_backend_pid(),txid_current(),c.recipient_id,d.care_recipient_id,'verified_whatsapp_receipt');
 perform set_config('hca.verified_whatsapp_provider',p_provider_id,true);
 result:=public.verified_legacy_whatsapp_receipt(p_provider_id,p_phone,p_hash);
 delete from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current();
 perform set_config('hca.verified_whatsapp_provider',coalesce(previous,''),true);
 return result;
end;$$;
alter function public.ingest_whatsapp_report(text,text,text,jsonb,text) rename to v3_ingest_whatsapp_report;
revoke all on function public.v3_ingest_whatsapp_report(text,text,text,jsonb,text) from public,anon,authenticated,service_role;
create function public.ingest_whatsapp_report(p_provider_id text,p_phone text,p_text text,p_lines jsonb,p_kind text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare c jsonb;result jsonb;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'webhook worker required' using errcode='42501';end if;
 c:=public.inbound_report_context(p_phone);if c is null then return jsonb_build_object('needsAuthenticatedSelection',true);end if;
 insert into private.worker_authority values(pg_backend_pid(),txid_current(),(c->>'userId')::uuid,(c->>'patientId')::uuid,'pending_whatsapp_report');
 result:=public.v3_ingest_whatsapp_report(p_provider_id,p_phone,p_text,p_lines,p_kind);
 delete from private.worker_authority where backend_pid=pg_backend_pid() and transaction_id=txid_current();return result;
end;$$;
grant execute on function public.ingest_whatsapp_report(text,text,text,jsonb,text) to service_role;

create table public.science_challenges (
 id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.requisition_notifications(id),
 document_id uuid not null references public.requisitions(id),recipient_id uuid not null references public.profiles(id),
 token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),phone text not null,document_version integer not null,
 expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now()
);
alter table public.science_challenges enable row level security;
revoke all on public.science_challenges from public,anon,authenticated,service_role;
create function public.issue_science_challenge(p_notification uuid,p_worker uuid,p_hash text) returns boolean
language plpgsql security definer set search_path='' as $$
declare n public.requisition_notifications;s public.requisition_lifecycle;d public.operational_documents;phone text;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' or not public.validate_notification_job(p_notification,p_worker) then raise exception 'verified worker required' using errcode='42501';end if;
 select * into n from public.requisition_notifications where id=p_notification;
 select * into d from public.operational_documents where id=n.document_id;
 select * into s from public.requisition_lifecycle where requisition_id=d.id;
 if d.type<>'REQ' or d.status='cancelled' or n.event_key<>'req.issued' or not(n.recipient_user_id=any(s.eligible_users))
 or not coalesce((s.policy->>'scienceWhatsApp')::boolean,false)
 or not coalesce((select (notification_preferences->>'scienceWhatsApp')::boolean from public.profiles where id=n.recipient_user_id),false)
 or not private.member_can(d.care_recipient_id,n.recipient_user_id,'req.science')
 or not exists(select 1 from public.document_events where id=n.document_event_id and version=d.version)
 or not exists(select 1 from public.meta_template_versions where name='hca_req_ciencia_simplificada_v4' and approval='APPROVED') then return false;end if;
 select v.phone into phone from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=n.recipient_user_id and u.phone_confirmed_at is not null and '+'||ltrim(u.phone,'+')=v.phone and ltrim(v.phone,'+')=ltrim(n.destination,'+');
 if phone is null then return false;end if;
 insert into public.science_challenges(notification_id,document_id,recipient_id,token_hash,phone,document_version,expires_at) values(n.id,d.id,n.recipient_user_id,p_hash,phone,d.version,now()+interval '10 minutes');return true;
end;$$;
create function public.confirm_whatsapp_science(p_provider_id text,p_phone text,p_hash text) returns boolean
language plpgsql security definer set search_path='' as $$
declare c public.science_challenges;d public.operational_documents;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'verified webhook required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('inbound:'||p_provider_id,0));
 if exists(select 1 from public.inbound_messages where provider_id=p_provider_id) then return false;end if;
 select * into c from public.science_challenges where token_hash=p_hash for update;
 if not found or c.used_at is not null or c.expires_at<=now() or c.phone<>'+'||ltrim(p_phone,'+') then return false;end if;
 select * into strict d from public.operational_documents where id=c.document_id;
 perform pg_advisory_xact_lock(hashtextextended('stock:'||d.care_recipient_id,0));
 select * into strict d from public.operational_documents where id=c.document_id for update;
 if d.status='cancelled' or d.version<>c.document_version or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=c.recipient_id and v.phone=c.phone and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null)
 or not coalesce((select (notification_preferences->>'scienceWhatsApp')::boolean from public.profiles where id=c.recipient_id),false) then return false;end if;
 if not private.record_science(d.id,c.recipient_id,'whatsapp_confirm',jsonb_build_object('providerId',p_provider_id,'notificationId',c.notification_id,'documentVersion',c.document_version,'challengeId',c.id)) then return false;end if;
 update public.science_challenges set used_at=now() where id=c.id;
 insert into public.inbound_messages values(p_provider_id,encode(extensions.digest(p_phone,'sha256'),'hex'),'science','processed',now());return true;
end;$$;
grant execute on function public.issue_science_challenge(uuid,uuid,text),public.confirm_whatsapp_science(text,text,text) to service_role;

alter function public.notification_webhook(text,text,uuid) rename to v3_notification_webhook;
revoke all on function public.v3_notification_webhook(text,text,uuid) from public,anon,authenticated,service_role;
create function public.notification_webhook(p_provider_reference text,p_state text,p_notification_id uuid default null) returns void
language plpgsql security definer set search_path='' as $$
declare n public.requisition_notifications;s public.requisition_lifecycle;begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'service authorization required' using errcode='42501';end if;
 perform public.v3_notification_webhook(p_provider_reference,p_state,p_notification_id);
 if p_state<>'read' then return;end if;
 select * into n from public.requisition_notifications where provider_reference=p_provider_reference and state='read' and channel='whatsapp' and event_key='req.issued' and template_name in ('hca_req_ciencia_familia_v4','hca_req_ciencia_simplificada_v4');
 if not found or n.template_snapshot is null then return;end if;
 select * into s from public.requisition_lifecycle where requisition_id=n.document_id;
 if not coalesce((s.policy->>'scienceAutomatic')::boolean,false)
 or not coalesce((select (notification_preferences->>'scienceAutomatic')::boolean from public.profiles where id=n.recipient_user_id),false)
 or not exists(select 1 from public.verified_phones v join auth.users u on u.id=v.user_id where v.user_id=n.recipient_user_id and ltrim(v.phone,'+')=ltrim(n.destination,'+') and '+'||ltrim(u.phone,'+')=v.phone and u.phone_confirmed_at is not null) then return;end if;
 perform private.record_science(n.document_id,n.recipient_user_id,'whatsapp_read',jsonb_build_object('providerReference',p_provider_reference,'notificationId',n.id,'documentEventId',n.document_event_id,'template',n.template_name,'templateVersion',n.template_version));
end;$$;
grant execute on function public.notification_webhook(text,text,uuid) to service_role;

